export interface AdminSecurityComponent {
  /** Weighted Security Score component key. */
  key: string;
  /** Plain-English, token-free label. */
  label: string;
  /**
   * 0–100 component score (unknown components are scored 0).
   * @minimum 0
   * @maximum 100
   */
  score: number;
  /** False when the signal could not be verified (honest UNKNOWN — scored 0, never assumed secure). */
  known: boolean;
}

/**
 * Honest tri-state-plus for a protection control. ACTIVE = verified on; INACTIVE = verified off; FUTURE_READY = wired but owned by a later phase; UNKNOWN = could not be verified.

 */
export type AdminSecurityControlStatus =
  (typeof AdminSecurityControlStatus)[keyof typeof AdminSecurityControlStatus];

export const AdminSecurityControlStatus = {
  ACTIVE: "ACTIVE",
  INACTIVE: "INACTIVE",
  FUTURE_READY: "FUTURE_READY",
  UNKNOWN: "UNKNOWN",
} as const;

/**
 * Protection/encryption status. Boolean/enum signals only — never any secret value.
 */
export interface AdminSecurityEncryption {
  /** True when the active encryption-at-rest key version is configured. */
  encryptionKeyConfigured: boolean;
  /** True when the server session/signing secret is configured. */
  secretsConfigured: boolean;
  /** True/false when the email provider can be resolved; null when it could not be determined. */
  emailProviderConfigured: boolean | null;
  /** True when the command-signing secret used by the MT5 bridge is configured. */
  bridgeSecretConfigured: boolean;
  /** True when the redaction self-test confirms tokens/API keys are scrubbed. */
  tokenRedactionActive: boolean;
  /** True when secret redaction is enabled and the self-test passes. */
  auditRedactionActive: boolean;
  commandSigningStatus: AdminSecurityControlStatus;
  idempotencyStatus: AdminSecurityControlStatus;
  replayProtectionStatus: AdminSecurityControlStatus;
  promptInjectionGuardStatus: AdminSecurityControlStatus;
  memoryBoundariesStatus: AdminSecurityControlStatus;
  /** True/false when a legacy-plaintext scan ran; null when not scanned (honest unknown). */
  legacyUnencryptedDetected?: boolean | null;
}

export interface AdminSecurityAuditChain {
  /** True when the tamper-evident hash chain recomputes and links cleanly. */
  valid: boolean;
  /**
   * Number of chained rows verified.
   * @minimum 0
   */
  checked: number;
  /**
   * Rows written with an honest UNKNOWN hash (never a fake link).
   * @minimum 0
   */
  unknownCount: number;
  /** First break reason when invalid; null when valid. */
  reason?: string | null;
}

