/**
 * live = real market data; demo = MT5 demo bridge context; mock = simulation provider (never safe as tradable truth); dev = developer test data; unknown = unrecognized source.

 */
export type ChartCandleSourceMode =
  (typeof ChartCandleSourceMode)[keyof typeof ChartCandleSourceMode];

export const ChartCandleSourceMode = {
  live: "live",
  demo: "demo",
  mock: "mock",
  dev: "dev",
  unknown: "unknown",
} as const;

/**
 * BID = MT5 broker bid-based bars; MID = bid-ask midpoint (forex/metals REST); LAST = exchange last price (indices/stocks/crypto); SYNTHETIC = Deriv volatility algorithm; UNKNOWN = provider not identified.

 */
export type ChartCandlePriceBasis =
  (typeof ChartCandlePriceBasis)[keyof typeof ChartCandlePriceBasis];

export const ChartCandlePriceBasis = {
  BID: "BID",
  MID: "MID",
  LAST: "LAST",
  SYNTHETIC: "SYNTHETIC",
  UNKNOWN: "UNKNOWN",
} as const;

export type ChartCandleQualityFlagsItem =
  (typeof ChartCandleQualityFlagsItem)[keyof typeof ChartCandleQualityFlagsItem];

export const ChartCandleQualityFlagsItem = {
  OHLC_INVALID: "OHLC_INVALID",
  TIMESTAMP_INVALID: "TIMESTAMP_INVALID",
  OUTLIER_SPIKE: "OUTLIER_SPIKE",
  OUTLIER_WICK: "OUTLIER_WICK",
  ZERO_VOLUME_GHOST: "ZERO_VOLUME_GHOST",
  HISTORICAL_PERIOD_SHIFT: "HISTORICAL_PERIOD_SHIFT",
  FORMING_BAR: "FORMING_BAR",
  MOCK_DATA: "MOCK_DATA",
  DUPLICATE_BUCKET: "DUPLICATE_BUCKET",
  STALE_FROM_PREV_TF: "STALE_FROM_PREV_TF",
} as const;

/**
 * ARX Verified Candle — Phase 1 truth contract. Every bar carries the full VerifiedCandle shape: identity, OHLCV, source metadata, quality flags, and completion status. Quality flags are advisory; flagged bars are never dropped.

 */
export interface ChartCandle {
  /** ARX-canonical symbol */
  symbol: string;
  /** Friendly display name */
  displaySymbol: string;
  timeframe: ChartCandleTimeframe;
  /** ISO 8601 bar open time */
  openTime: string;
  /** ISO 8601 bar close time */
  closeTime: string;
  open: number;
  high: number;
  low: number;
  close: number;
  /** Real traded volume when the provider supplies it */
  volume: number;
  /**
   * Verified tick count when a provider supplies one; null otherwise (e.g. synthetic indices / current REST adapters)
   * @nullable
   */
  tickVolume: number | null;
  /** Provider id that served this bar */
  source: string;
  /** false for the still-forming most-recent bar */
  isComplete: boolean;
  /** Task #496 — true ONLY for a server-synthesized real-time tip composed from live EA ticks (isComplete=false, isFinal=false). A closed provider bar is isForming=false. Analysis / Ruby / chart-intelligence exclude isForming bars (closed-bars-only); the tip is display telemetry, never persisted and never an execution input.
   */
  isForming: boolean;
  /** live = real market data; demo = MT5 demo bridge context; mock = simulation provider (never safe as tradable truth); dev = developer test data; unknown = unrecognized source.
   */
  sourceMode: ChartCandleSourceMode;
  /** BID = MT5 broker bid-based bars; MID = bid-ask midpoint (forex/metals REST); LAST = exchange last price (indices/stocks/crypto); SYNTHETIC = Deriv volatility algorithm; UNKNOWN = provider not identified.
   */
  priceBasis: ChartCandlePriceBasis;
  /** Alias for isComplete. true when the bar's bucket is closed and will not be updated. */
  isFinal: boolean;
  /** ISO 8601 timestamp when this batch was fetched from the provider. */
  receivedAt: string;
  /**
   * The provider's own symbol string when it differs from the ARX canonical form; null when the provider uses the same symbol.
   * @nullable
   */
  providerSymbol?: string | null;
  /**
   * MT5 broker-facing symbol when source is mt5_broker; null for all other sources.
   * @nullable
   */
  brokerSymbol?: string | null;
  /** Advisory per-candle quality indicators. Multiple flags may appear on one bar. Bars are NEVER dropped — flags are purely informational. OHLC_INVALID: high < low or open/close outside high/low. TIMESTAMP_INVALID: bar timestamp unparseable. OUTLIER_SPIKE: single-bar move far beyond neighboring bars. OUTLIER_WICK: wick-to-range ratio extreme for this asset class (D1/H4 only). ZERO_VOLUME_GHOST: zero volume on a non-synthetic bar. HISTORICAL_PERIOD_SHIFT: bar from a different price epoch (e.g. real 2023
  XAUUSD history at ~$2000 while current price is ~$4300 — legitimate
  history, not a bad tick; chart Y-axis may need to auto-scale).
FORMING_BAR: bar is still open (closeTime in the future). MOCK_DATA: bar originated from a mock/simulation provider. DUPLICATE_BUCKET: another bar at this openTime was collapsed. STALE_FROM_PREV_TF: large gap before this bar suggests a timeframe carry-over.
 */
  qualityFlags: ChartCandleQualityFlagsItem[];
}

