/**
 * Historical + live seam analysis (Step 7). Reports the boundary between the last CLOSED bar and the FORMING bar. Identifies gaps and overlaps at the merge point so callers can detect missing/duplicate bars at the live edge.

 */
export interface ChartMergeSeamReport {
  /** true when the last bar(s) are still forming (closeTime in the future) */
  formingBarDetected: boolean;
  /** Number of still-forming bars at the trailing edge of the array */
  formingBarCount: number;
  /** true when there is a gap between the last closed bar and the first forming bar */
  gapAtSeam: boolean;
  /** true when the forming bar's open time overlaps the last closed bar */
  overlapAtSeam: boolean;
  /** Number of missing bar intervals at the seam (0 when no gap) */
  seamGapIntervals: number;
}

